          "Vállalaton belüli (1 cég) · nemzeti (cégek 1 országban) · nemzetközi (országok)",
          "Vertikális = különböző termelési szintek · horizontális = azonos szint, más termékek",
          "Szektorok: primer (őstermelés) · szekunder (termelés) · tercier (szolgáltatás)"
